import time
from lease_guard import LeaseGuard

def test_lease_validity_boundary():
    # Test that a lease held exactly at its expiration is no longer valid
    lg = LeaseGuard()
    lg.acquire("lock1", "nodeA", 0.0)  # Lease expires immediately
    time.sleep(0.01)  # Ensure time advances past lease expiration
    assert lg.holds_lease("lock1", "nodeA") is False
